select jsonb_build_object(
'data',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'table',c.relname,'fingerprint',(xpath('//payload/text()',query_to_xml(format('select count(*)::text || ''|'' || encode(extensions.digest(convert_to(coalesce(string_agg(to_jsonb(t)::text, E''\\n'' order by to_jsonb(t)::text), ''''), ''UTF8''), ''sha256''), ''hex'') as payload from %I.%I t',n.nspname,c.relname),false,false,'')))[1]::text) order by n.nspname,c.relname) from pg_class c join pg_namespace n on n.oid=c.relnamespace where c.relkind='r' and (n.nspname='public' or (n.nspname='auth' and c.relname in ('users','sessions')) or (n.nspname='storage' and c.relname in ('objects','buckets')))),
'migrations',(select jsonb_agg(jsonb_build_object('version',version,'name',name,'statement_count',cardinality(statements),'normalized_sha256',encode(extensions.digest(convert_to(btrim(replace(array_to_string(statements,E'\n'),E'\r',''),E' \t\n\r'),'UTF8'),'sha256'),'hex')) order by version) from supabase_migrations.schema_migrations),
'metadata',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'name',p.proname,'args',pg_get_function_identity_arguments(p.oid),'sha256',encode(extensions.digest(convert_to(pg_get_functiondef(p.oid),'UTF8'),'sha256'),'hex'),'acl',p.proacl::text) order by n.nspname,p.proname,pg_get_function_identity_arguments(p.oid)) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in ('public','private') and p.prokind='f')
) as baseline;
